fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(n, vals_2.len(), "vals_1 and vals_2 must have the same length");
    assert_eq!(n, conds_1.len(), "vals_1 and conds_1 must have the same length");
    assert_eq!(n, conds_2.len(), "vals_1 and conds_2 must have the same length");

    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let v = match (conds_1[i], conds_2[i]) {
            (true, true) => (vals_1[i] + vals_2[i]) / 2,
            (true, false) => vals_1[i],
            (false, true) => vals_2[i],
            (false, false) => unreachable!("At least one condition must be true at index {}", i),
        };
        avgs.push(v);
    }
}